# Import of required libraries
import skyramp
import os
import time
import json


from SkyrampUtils import (
    URL_localhost,
    create_category,
    create_recipe,
    delete_recipe,
    get_recipe_statistics,
    update_recipe,
)


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["Authorization"] = "Bearer " + os.getenv("SKYRAMP_TEST_TOKEN")

    statistics_GET_response = get_recipe_statistics(client, headers)

    baseline_total = skyramp.get_response_value(statistics_GET_response, "total")
    assert baseline_total is not None
    assert baseline_total >= 0
    assert skyramp.check_schema(statistics_GET_response, r'''{"total": 0, "by_category": {}}''')

    categories_POST_response = create_category(client, headers, "SkyrampStatsCategory")

    category_name = skyramp.get_response_value(categories_POST_response, "name")
    assert category_name.startswith("SkyrampStatsCategory-")
    assert skyramp.get_response_value(categories_POST_response, "slug") == category_name.lower()
    assert skyramp.get_response_value(categories_POST_response, "id") is not None

    recipes_POST_response = create_recipe(client, headers, "Skyramp Stats Recipe A")

    recipes = json.loads(recipes_POST_response.response_body)
    assert recipes.startswith("skyramp-stats-recipe-a-")

    recipes_recipes_PATCH_response = update_recipe(
        client, headers, recipes, categories_POST_response
    )

    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "slug") == recipes
    assert skyramp.get_response_value(
        recipes_recipes_PATCH_response, "recipeCategory.0.name"
    ) == category_name

    recipes_POST_1_response = create_recipe(client, headers, "Skyramp Stats Recipe B")

    recipes_1 = json.loads(recipes_POST_1_response.response_body)
    assert recipes_1.startswith("skyramp-stats-recipe-b-")
    assert recipes_1 != recipes

    recipes_recipes_PATCH_1_response = update_recipe(
        client, headers, recipes_1, categories_POST_response
    )

    assert skyramp.get_response_value(recipes_recipes_PATCH_1_response, "slug") == recipes_1
    assert skyramp.get_response_value(
        recipes_recipes_PATCH_1_response, "recipeCategory.0.name"
    ) == category_name

    statistics_GET_1_response = get_recipe_statistics(client, headers)

    statistics_GET_1_body = json.loads(statistics_GET_1_response.response_body)
    assert statistics_GET_1_body["total"] == baseline_total + 2
    assert statistics_GET_1_body["by_category"][category_name] == 2

    recipes_recipes_DELETE_response = delete_recipe(
        client, headers, skyramp.get_response_value(recipes_recipes_PATCH_response, "slug")
    )

    recipes_recipes_DELETE_1_response = delete_recipe(
        client, headers, skyramp.get_response_value(recipes_recipes_PATCH_1_response, "slug")
    )


if __name__ == "__main__":
    test_integration()
